package vn.smartfarm.iot.irrigation;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.sql.Timestamp;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.web.servlet.MockMvc;
import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=false","smartfarm.irrigation.demo-enabled=false","smartfarm.irrigation.monitor-enabled=true","smartfarm.irrigation-queue.scheduling-enabled=false"})
@AutoConfigureMockMvc @EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class CircuitValveHistoryTest {
 @Autowired CircuitValveMonitor monitor;@Autowired CircuitValveHistory history;@Autowired IrrigationCircuits circuits;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired MockMvc mvc;
 @Autowired org.springframework.transaction.PlatformTransactionManager transactionManager;
 Instant base;long commands,runs,queue;final UUID boot=UUID.fromString("83000000-0000-4000-8000-000000000001"),nextBoot=UUID.fromString("83000000-0000-4000-8000-000000000002");
 @BeforeEach void setup(){clean();jdbc.update("INSERT INTO irrigation_demo_binding(singleton) VALUES(1) ON CONFLICT DO NOTHING");jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES('HWATER','History water','AREA001','WATER',2)");jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES('HWATER','LOW','WATER_PRESENT','boolean'),('HWATER','FLOW','FLOW_RATE','L/min')");for(int i=1;i<=2;i++){
  jdbc.update("INSERT INTO iot_node(node_id,name,area_id,node_type,telemetry_version) VALUES(?,'History soil','AREA001','SOIL',2)","HSOIL"+i);for(int c=1;c<=3;c++)jdbc.update("INSERT INTO iot_channel(node_id,channel_id,metric,unit) VALUES(?,?,'SOIL_MOISTURE','%')","HSOIL"+i,"SOIL"+c);
  jdbc.update("INSERT INTO irrigation_zone(zone_id,name,area_id,soil_node_id,expected_source,dry_threshold,wet_threshold) VALUES(?,'History zone','AREA001',?,'SIMULATOR',30,35)","HZONE"+i,"HSOIL"+i);
  circuits.create(mapper.createObjectNode().put("circuitId","HISTC"+i).put("name","Nhánh lịch sử "+i).put("zoneId","HZONE"+i).put("zoneRevision",1).put("controllerId","IRRIGATION0"+(i+5)).put("valveId","VALVE0"+(i+5)).put("pumpId","PUMP01").put("waterNodeId","HWATER").put("lowChannelId","LOW").put("flowChannelId","FLOW").put("expectedSource","SIMULATOR"));
 }base=Instant.now().minusSeconds(3);commands=count("pump_command")+count("irrigation_demo_command");runs=count("watering_run");queue=count("irrigation_queue_request");}
 void clean(){jdbc.update("DELETE FROM irrigation_circuit WHERE circuit_id IN ('HISTC1','HISTC2')");jdbc.update("DELETE FROM irrigation_zone WHERE zone_id IN ('HZONE1','HZONE2')");jdbc.update("DELETE FROM iot_node WHERE node_id IN ('HSOIL1','HSOIL2','HWATER')");}
 @AfterEach void cleanup(){try{assertEquals(commands,count("pump_command")+count("irrigation_demo_command"));assertEquals(runs,count("watering_run"));assertEquals(queue,count("irrigation_queue_request"));}finally{clean();}}
 long count(String table){return jdbc.queryForObject("SELECT COUNT(*) FROM "+table,Long.class);}
 ObjectNode packet(int i,int seq){var p=mapper.createObjectNode().put("schemaVersion",1).put("controllerId","IRRIGATION0"+(i+5)).put("actuatorId","VALVE0"+(i+5)).put("circuitId","HISTC"+i).put("circuitRevision",1).put("zoneId","HZONE"+i).put("zoneRevision",1).put("bootId",boot.toString()).put("sequence",seq).put("timestamp",base.plusMillis(seq).toString()).put("dataSource","SIMULATOR").put("monitorOnly",true).put("demoEnabled",false).put("gpioState","CLOSED").put("lastOrdinal",0).put("reason","BOOT").put("feedbackState","CLOSED");p.putObject("positionFeedback").put("version",1).put("enabled",true).put("state","CLOSED").putNull("fault");return p;}
 void receive(int i,ObjectNode p)throws Exception{monitor.receive("smartfarm/FARM001/VALVE0"+(i+5)+"/status",mapper.writeValueAsBytes(p),false);}
 CircuitValveHistory.Page list(String circuit,String valve,String condition,int limit,String cursor){return history.list(base.minusSeconds(1),base.plusSeconds(10),circuit,valve,condition,limit,cursor);}
 @Test void acceptedSampleStoresOriginalConfigurationAndBothClocks()throws Exception{receive(1,packet(1,0));var p=list("HISTC1",null,null,50,null);assertEquals(1,p.items().size());var row=p.items().getFirst();assertEquals(mapper.valueToTree(circuits.find("HISTC1")),row.circuitSnapshot());assertEquals(monitor.latest("VALVE06"),mapper.treeToValue(row.observation(),CircuitValveMonitor.Observation.class));assertNotEquals(row.observation().path("observedAt"),row.observation().path("receivedAt"));}
 @Test void duplicateAndOutOfOrderPacketsDoNotAppendOrRenew()throws Exception{receive(1,packet(1,1));var first=list("HISTC1",null,null,50,null);receive(1,packet(1,1));receive(1,packet(1,0));assertEquals(first,list("HISTC1",null,null,50,null));}
 @Test void malformedStaleRetainedAndBorrowedPacketsNeverBecomeHistory()throws Exception{for(var p:List.of(packet(1,0).put("timestamp",Instant.now().minusSeconds(16).toString()),packet(1,0).put("controllerId","IRRIGATION09"),packet(1,0).put("dataSource","PHYSICAL"),packet(1,0).put("circuitRevision",2)))assertThrows(IllegalArgumentException.class,()->receive(1,p));assertThrows(IllegalArgumentException.class,()->monitor.receive("smartfarm/FARM001/VALVE06/status",mapper.writeValueAsBytes(packet(1,0)),true));assertTrue(list("HISTC1",null,null,50,null).items().isEmpty());}
 @Test void retiredBootCannotAddHistoryAfterNewBoot()throws Exception{receive(1,packet(1,0));receive(1,packet(1,1).put("bootId",nextBoot.toString()));receive(1,packet(1,2));assertEquals(2,list("HISTC1",null,null,50,null).items().size());}
 @Test void missingPositionCapabilityRemainsUnknown()throws Exception{var p=packet(1,0).put("feedbackState","UNKNOWN");p.remove("positionFeedback");receive(1,p);var row=list(null,"VALVE06","UNKNOWN",50,null).items().getFirst();assertTrue(row.observation().get("positionFeedback").isNull());assertTrue(list(null,"VALVE06","CLOSED",50,null).items().isEmpty());}
 @Test void faultFilterIncludesDeviceFaultEvenWithClosedSwitch()throws Exception{receive(1,packet(1,0).put("reason","DEVICE_FAULT"));assertEquals(1,list(null,"VALVE06","FAULT",50,null).items().size());assertEquals(1,list(null,"VALVE06","CLOSED",50,null).items().size());}
 @Test void filtersSeparateCircuitsAndValvesWithoutBorrowing()throws Exception{receive(1,packet(1,0));receive(2,packet(2,0));assertEquals(1,list("HISTC2",null,null,50,null).items().size());assertTrue(list("HISTC1","VALVE07",null,50,null).items().isEmpty());assertTrue(list("HISTC1","VALVE06","FAULT",50,null).items().isEmpty());}
 @Test void timeRangeUsesReceiptAndHasExclusiveEnd()throws Exception{receive(1,packet(1,0));var s=monitor.latest("VALVE06");assertTrue(history.list(s.observedAt().minusMillis(1),s.observedAt().plusMillis(1),"HISTC1",null,null,50,null).items().isEmpty());assertTrue(history.list(base,s.receivedAt(),"HISTC1",null,null,50,null).items().isEmpty());assertEquals(1,history.list(s.receivedAt(),s.receivedAt().plusSeconds(1),"HISTC1",null,null,50,null).items().size());}
 @Test void paginationUsesIdAsTieBreakerAndNeverRepeats()throws Exception{for(int i=0;i<3;i++)receive(1,packet(1,i));Instant same=Instant.now();jdbc.update("UPDATE circuit_valve_history SET received_at=?,observation=jsonb_set(observation,'{receivedAt}',to_jsonb(?::text)) WHERE circuit_id='HISTC1'",Timestamp.from(same),same.toString());var ids=new ArrayList<Long>();String token=null;do{var page=list("HISTC1",null,null,1,token);ids.add(page.items().getFirst().id());token=page.nextCursor();}while(token!=null);assertEquals(3,new HashSet<>(ids).size());assertTrue(ids.get(0)>ids.get(1)&&ids.get(1)>ids.get(2));}
 @Test void laterInsertCannotEnterAnExistingPageSnapshot()throws Exception{receive(1,packet(1,0));receive(1,packet(1,1));var first=list("HISTC1",null,null,1,null);receive(1,packet(1,2));var second=list("HISTC1",null,null,1,first.nextCursor());assertEquals(first.ceilingId(),second.ceilingId());assertNull(second.nextCursor());assertEquals(3,list("HISTC1",null,null,50,null).items().size());}
 @Test void cursorCannotCrossRangeCircuitValveOrCondition()throws Exception{receive(1,packet(1,0));receive(1,packet(1,1));String token=list("HISTC1","VALVE06","CLOSED",1,null).nextCursor();assertNotNull(token);assertThrows(Exception.class,()->list("HISTC2","VALVE06","CLOSED",1,token));assertThrows(Exception.class,()->list("HISTC1","VALVE07","CLOSED",1,token));assertThrows(Exception.class,()->list("HISTC1","VALVE06","FAULT",1,token));assertThrows(Exception.class,()->history.list(base,base.plusSeconds(10),"HISTC1","VALVE06","CLOSED",1,token));}
 @Test void changedMappingDoesNotRewriteOldHistoryOrBackfillANewSample()throws Exception{receive(1,packet(1,0));var first=list("HISTC1",null,null,50,null).items().getFirst();circuits.update("HISTC1",((ObjectNode)mapper.valueToTree(circuits.find("HISTC1"))).put("name","Tên mới"));assertEquals(first,list("HISTC1",null,null,50,null).items().getFirst());receive(1,packet(1,1).put("bootId",nextBoot.toString()).put("circuitRevision",2));var all=list("HISTC1",null,null,50,null).items();assertEquals(2,all.size());assertEquals(2,all.getFirst().circuitSnapshot().path("revision").asInt());assertEquals(1,all.getLast().circuitSnapshot().path("revision").asInt());}
 @Test void historyFailureRollsBackStatusBootAndEpisode()throws Exception{jdbc.execute("ALTER TABLE circuit_valve_history ADD CONSTRAINT v29_test_reject CHECK(circuit_id<>'HISTC1')");try{assertThrows(RuntimeException.class,()->receive(1,packet(1,0).put("reason","DEVICE_FAULT")));assertNull(monitor.latest("VALVE06"));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM circuit_valve_boot WHERE valve_id='VALVE06'",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM circuit_valve_alert WHERE circuit_id='HISTC1'",Integer.class));assertTrue(list("HISTC1",null,null,50,null).items().isEmpty());}finally{jdbc.execute("ALTER TABLE circuit_valve_history DROP CONSTRAINT v29_test_reject");}}
 @Test void readsAndDisabledMonitorDoNotMutateOrRefreshHistory()throws Exception{receive(1,packet(1,0));var before=jdbc.queryForObject("SELECT row_to_json(h)::text FROM circuit_valve_history h WHERE circuit_id='HISTC1'",String.class);new CircuitValveMonitor(jdbc,null,null,history,false).topics();list("HISTC1",null,null,50,null);assertEquals(before,jdbc.queryForObject("SELECT row_to_json(h)::text FROM circuit_valve_history h WHERE circuit_id='HISTC1'",String.class));}
 @Test void httpValidatesQueryAndIsReadOnly()throws Exception{receive(1,packet(1,0));String url="/api/v1/valve-history";mvc.perform(get(url).param("from",base.toString()).param("to",base.plusSeconds(10).toString()).param("valveId","VALVE06")).andExpect(status().isOk()).andExpect(jsonPath("$.items[0].observation.actuatorId").value("VALVE06"));for(String[] pair:List.of(new String[]{"limit","0"},new String[]{"limit","201"},new String[]{"valveId","VALVE01"},new String[]{"circuitId","x' OR 1=1"},new String[]{"condition","bad"},new String[]{"cursor","bad"}))mvc.perform(get(url).param("from",base.toString()).param("to",base.plusSeconds(10).toString()).param(pair[0],pair[1])).andExpect(status().isBadRequest());mvc.perform(get(url).param("from",base.toString()).param("to",base.plus(Duration.ofDays(32)).toString())).andExpect(status().isBadRequest());mvc.perform(get(url).param("from","bad").param("to",base.toString())).andExpect(status().isBadRequest());assertEquals(1,list("HISTC1",null,null,50,null).items().size());}
 @Test void concurrentDuplicatePacketsAppendOnce()throws Exception{var p=packet(1,0);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{receive(1,p);return true;});var b=pool.submit(()->{receive(1,p);return true;});assertTrue(a.get(5,TimeUnit.SECONDS));assertTrue(b.get(5,TimeUnit.SECONDS));}assertEquals(1,list("HISTC1",null,null,50,null).items().size());}
 @Test void uncommittedEarlierReceiptCannotSlipIntoAnExistingPaginationSnapshot()throws Exception{
  receive(1,packet(1,0));receive(1,packet(1,1));var c=circuits.find("HISTC1");var p=(ObjectNode)mapper.valueToTree(monitor.latest("VALVE06"));p.put("bootId",nextBoot.toString()).put("sequence",0).put("receivedAt",base.plusMillis(500).toString());var observation=mapper.treeToValue(p,CircuitValveMonitor.Observation.class);
  var inserted=new CountDownLatch(1);var release=new CountDownLatch(1);
  try(var pool=Executors.newFixedThreadPool(2)){
   var pending=pool.submit(()->{new org.springframework.transaction.support.TransactionTemplate(transactionManager).executeWithoutResult(t->{history.record(c,observation);inserted.countDown();try{if(!release.await(5,TimeUnit.SECONDS))throw new IllegalStateException("Test release timed out");}catch(InterruptedException e){throw new IllegalStateException(e);}});return true;});
   try{assertTrue(inserted.await(3,TimeUnit.SECONDS));var later=pool.submit(()->{receive(2,packet(2,0));return true;});assertThrows(TimeoutException.class,()->later.get(150,TimeUnit.MILLISECONDS));var first=list("HISTC1",null,null,1,null);release.countDown();assertTrue(pending.get(3,TimeUnit.SECONDS));assertTrue(later.get(3,TimeUnit.SECONDS));var rest=list("HISTC1",null,null,10,first.nextCursor());assertEquals(1,rest.items().size());assertNull(rest.nextCursor());assertTrue(rest.items().getFirst().id()<=first.ceilingId());assertEquals(3,list("HISTC1",null,null,50,null).items().size());}finally{release.countDown();}
  }
 }
}
